import React, { useState } from "react";
import '../../style/navbar.css';
import { NavLink, useNavigate } from "react-router-dom";
import ApiService from "../../service/ApiService";
import { FaSearch, FaUser, FaShoppingCart, FaChevronDown, FaInfoCircle } from "react-icons/fa";

const Navbar = () => {
    const [searchValue, setSearchValue] = useState("");
    const [showShopDropdown, setShowShopDropdown] = useState(false);
    const [showUserDropdown, setShowUserDropdown] = useState(false);
    const navigate = useNavigate();

    const isAdmin = ApiService.isAdmin();
    const isAuthenticated = ApiService.isAuthenticated();

    const handleSearchChange = (e) => {
        setSearchValue(e.target.value);
    };

    const handleSearchSubmit = async (e) => {
        e.preventDefault();
        navigate(`/?search=${searchValue}`);
    };

    const handleLogout = () => {
        const confirm = window.confirm("Are you sure you want to logout?");
        if (confirm) {
            ApiService.logout();
            setTimeout(() => {
                navigate('/login');
            }, 500);
        }
    };

    return (
        <nav className="navbar">
            <div className="nav-container">
                <div className="nav-brand">
                    <NavLink to="/">
                        <img src="/phegon_mart.png" alt="Phegon Mart" className="logo-img" />
                    </NavLink>
                </div>

                <form className="search-form" onSubmit={handleSearchSubmit}>
                    <input
                        type="text"
                        placeholder="Search products..."
                        value={searchValue}
                        onChange={handleSearchChange}
                    />
                    <button type="submit" className="search-btn">
                        <FaSearch />
                    </button>
                </form>

                <div className="nav-links">
                    <NavLink to="/" exact activeClassName="active">Home</NavLink>
                    
                    <NavLink to="/about" activeClassName="active">
                        <FaInfoCircle className="nav-icon" /> About
                    </NavLink>

                    <div 
                        className="dropdown" 
                        onMouseEnter={() => setShowShopDropdown(true)} 
                        onMouseLeave={() => setShowShopDropdown(false)}
                    >
                        <span className="dropdown-toggle">
                            Shop <FaChevronDown className="dropdown-icon" />
                        </span>
                        {showShopDropdown && (
                            <div className="dropdown-menu">
                                <NavLink to="/categories">All Categories</NavLink>
                                <NavLink to="/products">Featured Products</NavLink>
                                {isAdmin && <NavLink to="/admin/products">Manage Products</NavLink>}
                            </div>
                        )}
                    </div>

                    {isAuthenticated && (
                        <div 
                            className="dropdown" 
                            onMouseEnter={() => setShowUserDropdown(true)} 
                            onMouseLeave={() => setShowUserDropdown(false)}
                        >
                            <span className="dropdown-toggle">
                                <FaUser className="user-icon" />
                            </span>
                            {showUserDropdown && (
                                <div className="dropdown-menu">
                                    <NavLink to="/profile">My Profile</NavLink>
                                    <NavLink to="/orders">My Orders</NavLink>
                                    <span onClick={handleLogout}>Logout</span>
                                </div>
                            )}
                        </div>
                    )}

                    <NavLink to="/cart" className="cart-link">
                        <FaShoppingCart />
                        {isAuthenticated && <span className="cart-badge">{/* Add cart count here */}</span>}
                    </NavLink>

                    {!isAuthenticated && (
                        <NavLink to="/login" className="auth-link">
                            <FaUser /> Login
                        </NavLink>
                    )}
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
